import { test } from 'node:test';
import assert from 'node:assert/strict';
import { receiptTotal } from '../src/total.js';

test('lines are summed', () => {
  assert.equal(receiptTotal([{ price: 120, qty: 2 }, { price: 300, qty: 1 }]), 540);
});

test('no discount keeps the subtotal', () => {
  assert.equal(receiptTotal([{ price: 999, qty: 1 }], 0), 999);
});

// #42
test('300 yen at 30 % is 210 yen', () => {
  assert.equal(receiptTotal([{ price: 300, qty: 1 }], 30), 210);
});

// review of #43: a discount outside 0..100 whole percent is refused, not computed
test('a negative discount is a RangeError', () => {
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], -5), RangeError);
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], -1), RangeError);
});

test('a discount over 100 % is a RangeError', () => {
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], 120), RangeError);
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], 101), RangeError);
});

test('a discount that is not a whole number is a RangeError', () => {
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], 12.5), RangeError);
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], NaN), RangeError);
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], '30'), RangeError);
  // a value that cannot be put into the message is still a RangeError
  assert.throws(() => receiptTotal([{ price: 300, qty: 1 }], Symbol('30')), RangeError);
});

test('0 % and 100 % are the ends of the range and are accepted', () => {
  assert.equal(receiptTotal([{ price: 300, qty: 1 }], 0), 300);
  assert.equal(receiptTotal([{ price: 300, qty: 1 }], 100), 0);
});
